1	package net.wolfig.codeowls.lexer;
2	
3	import com.intellij.lexer.LexerBase;
4	import com.intellij.psi.TokenType;
5	import com.intellij.psi.tree.IElementType;
6	import org.jetbrains.annotations.NotNull;
7	import org.jetbrains.annotations.Nullable;
8	
9	/**
10	 * Handwritten lexer for CODEOWNERS files.
11	 *
12	 * <p>Each line is one of:
13	 * <ul>
14	 *   <li>Empty / whitespace-only</li>
15	 *   <li>Comment: {@code # text}</li>
16	 *   <li>GitLab section header: {@code [Name]} or {@code ^[Name]} (optional section),
17	 *       optionally followed by an approval count {@code [N]} and/or default owners
18	 *       on the same line (e.g. {@code [Backend][2] @org/backend @alice})</li>
19	 *   <li>Rule: {@code pattern  owner1 owner2 …}</li>
20	 * </ul>
21	 *
22	 * <p>Patterns may begin with {@code !} to negate (GitLab). Owners may be users
23	 * ({@code @alice}), teams ({@code @org/team}), roles ({@code @@maintainer}), or
24	 * e-mail addresses ({@code alice@example.com}).
25	 *
26	 * <p>State is kept across {@link #advance()} calls so the lexer knows whether it
27	 * is at the start of a line, reading owners, or just after a section header.
28	 */
29	public class CodeownersLexer extends LexerBase {
30	
31	  // ---- states ----
32	  private static final int STATE_LINE_START = 0;     // beginning of any line
33	  private static final int STATE_OWNERS = 1;         // after the file-pattern token
34	  private static final int STATE_AFTER_SECTION = 2;  // after a [Section] token
35	
36	  private CharSequence buffer;
37	  private int bufferEnd;
38	  private int tokenStart;
39	  private int tokenEnd;
40	  private IElementType tokenType;
41	  private int state;
42	
43	  // ---- character predicates ----
44	
45	  private static boolean isNewline(char c) {
46	    return c == '\n' || c == '\r';
47	  }
48	
49	  private static boolean isHSpace(char c) {
50	    return c == ' ' || c == '\t';
51	  }
52	
53	  private static boolean isWhitespace(char c) {
54	    return isHSpace(c) || isNewline(c);
55	  }
56	
57	  private boolean peekIs(int offset, char expected) {
58	    return offset < bufferEnd && buffer.charAt(offset) == expected;
59	  }
60	
61	  // ---- LexerBase contract ----
62	
63	  @Override
64	  public void start(@NotNull CharSequence buffer, int startOffset, int endOffset, int initialState) {
65	    this.buffer = buffer;
66	    this.bufferEnd = endOffset;
67	    this.tokenEnd = startOffset;
68	    this.state = initialState;
69	    advance();
70	  }
71	
72	  @Override
73	  public int getState() {
74	    return state;
75	  }
76	
77	  @Override
78	  public @Nullable IElementType getTokenType() {
79	    return tokenType;
80	  }
81	
82	  @Override
83	  public int getTokenStart() {
84	    return tokenStart;
85	  }
86	
87	  @Override
88	  public int getTokenEnd() {
89	    return tokenEnd;
90	  }
91	
92	  @Override
93	  public @NotNull CharSequence getBufferSequence() {
94	    return buffer;
95	  }
96	
97	  @Override
98	  public int getBufferEnd() {
99	    return bufferEnd;
100	  }
101	
102	  @Override
103	  public void advance() {
104	    tokenStart = tokenEnd;
105	    if (tokenStart >= bufferEnd) {
106	      tokenType = null;
107	      return;
108	    }
109	    char c = buffer.charAt(tokenStart);
110	    switch (state) {
111	      case STATE_OWNERS:
112	        lexOwners(c);
113	        break;
114	      case STATE_AFTER_SECTION:
115	        lexAfterSection(c);
116	        break;
117	      case STATE_LINE_START:
118	      default:
119	        lexLineStart(c);
120	        break;
121	    }
122	  }
123	
124	  // ---- per-state lex methods ----
125	
126	  private void lexLineStart(char c) {
127	    if (isNewline(c)) {
128	      consumeNewline();
129	      tokenType = TokenType.WHITE_SPACE;
130	      state = STATE_LINE_START;
131	    } else if (isHSpace(c)) {
132	      consumeHSpace();
133	      tokenType = TokenType.WHITE_SPACE;
134	      // state stays STATE_LINE_START — leading whitespace before the pattern
135	    } else if (c == '#') {
136	      consumeToEol();
137	      tokenType = CodeownersTokenTypes.COMMENT;
138	      // state stays STATE_LINE_START (EOL will reset it on next advance)
139	    } else if (c == '[' || (c == '^' && peekIs(tokenStart + 1, '['))) {
140	      // [Section] or ^[Section] (GitLab optional-section flag).
141	      // consumeBracketed scans up to the closing ']' regardless of the opening
142	      // character, so it handles both forms in one path.
143	      consumeBracketed();
144	      tokenType = CodeownersTokenTypes.SECTION_HEADER;
145	      state = STATE_AFTER_SECTION;
146	    } else {
147	      consumeNonSpace();
148	      tokenType = CodeownersTokenTypes.PATTERN;
149	      state = STATE_OWNERS;
150	    }
151	  }
152	
153	  private void lexOwners(char c) {
154	    if (isNewline(c)) {
155	      consumeNewline();
156	      tokenType = TokenType.WHITE_SPACE;
157	      state = STATE_LINE_START;
158	    } else if (isHSpace(c)) {
159	      consumeHSpace();
160	      tokenType = TokenType.WHITE_SPACE;
161	    } else if (c == '@') {
162	      int start = tokenStart;
163	      consumeNonSpace();
164	      String token = buffer.subSequence(start, tokenEnd).toString();
165	      if (token.startsWith("@@")) {
166	        // @@maintainer / @@developer / @@developers (GitLab roles)
167	        tokenType = CodeownersTokenTypes.ROLE_OWNER;
168	      } else if (token.contains("/")) {
169	        // @org/team
170	        tokenType = CodeownersTokenTypes.TEAM_OWNER;
171	      } else {
172	        // @username
173	        tokenType = CodeownersTokenTypes.USER_OWNER;
174	      }
175	    } else {
176	      int start = tokenStart;
177	      consumeNonSpace();
178	      // email owner: contains '@' somewhere after position 0
179	      String token = buffer.subSequence(start, tokenEnd).toString();
180	      tokenType = token.indexOf('@') > 0 ? CodeownersTokenTypes.EMAIL_OWNER : CodeownersTokenTypes.BAD_CHARACTER;
181	    }
182	  }
183	
184	  private void lexAfterSection(char c) {
185	    if (isNewline(c)) {
186	      consumeNewline();
187	      tokenType = TokenType.WHITE_SPACE;
188	      state = STATE_LINE_START;
189	    } else if (isHSpace(c)) {
190	      consumeHSpace();
191	      tokenType = TokenType.WHITE_SPACE;
192	    } else if (c == '[') {
193	      // Approval count [N] may appear once, directly after the section header.
194	      // Anything that follows is treated as default owners for the section.
195	      consumeBracketed();
196	      tokenType = CodeownersTokenTypes.APPROVAL_COUNT;
197	      state = STATE_OWNERS;
198	    } else {
199	      // GitLab allows default owners on the same line as the section header,
200	      // e.g. "[Backend][2] @org/backend @alice". Delegate to owner lexing.
201	      state = STATE_OWNERS;
202	      lexOwners(c);
203	    }
204	  }
205	
206	  // ---- character-advance helpers ----
207	
208	  private void consumeNewline() {
209	    tokenEnd = tokenStart + 1;
210	    // absorb \r\n as a single whitespace token
211	    if (buffer.charAt(tokenStart) == '\r' && tokenEnd < bufferEnd && buffer.charAt(tokenEnd) == '\n') {
212	      tokenEnd++;
213	    }
214	  }
215	
216	  private void consumeHSpace() {
217	    tokenEnd = tokenStart + 1;
218	    while (tokenEnd < bufferEnd && isHSpace(buffer.charAt(tokenEnd))) tokenEnd++;
219	  }
220	
221	  private void consumeToEol() {
222	    tokenEnd = tokenStart + 1;
223	    while (tokenEnd < bufferEnd && !isNewline(buffer.charAt(tokenEnd))) tokenEnd++;
224	  }
225	
226	  private void consumeNonSpace() {
227	    tokenEnd = tokenStart + 1;
228	    while (tokenEnd < bufferEnd && !isWhitespace(buffer.charAt(tokenEnd))) tokenEnd++;
229	  }
230	
231	  /**
232	   * Advances past {@code [...]} including both brackets. Stops at EOL if {@code ']'} is missing.
233	   */
234	  private void consumeBracketed() {
235	    tokenEnd = tokenStart + 1;
236	    while (tokenEnd < bufferEnd && buffer.charAt(tokenEnd) != ']' && !isNewline(buffer.charAt(tokenEnd))) {
237	      tokenEnd++;
238	    }
239	    if (tokenEnd < bufferEnd && buffer.charAt(tokenEnd) == ']') tokenEnd++;
240	  }
241	}
