1	package net.wolfig.codeowls.navigation;
2	
3	import com.intellij.codeInsight.navigation.actions.GotoDeclarationHandler;
4	import com.intellij.lang.ASTNode;
5	import com.intellij.openapi.editor.Editor;
6	import com.intellij.openapi.project.Project;
7	import com.intellij.psi.PsiElement;
8	import com.intellij.psi.tree.IElementType;
9	import net.wolfig.codeowls.lexer.CodeownersTokenTypes;
10	import org.jetbrains.annotations.Nullable;
11	
12	/**
13	 * Makes user and team owners in a CODEOWNERS file Ctrl+Clickable: navigating to
14	 * an owner opens that user's or group's page on the project's Git hosting
15	 * platform (GitHub, GitLab, …) in the external browser.
16	 *
17	 * <p>The target URL is computed by {@link CodeownersRemoteService} from the
18	 * repository's Git remote. When the project has no Git remote, or the owner is
19	 * a role ({@code @@maintainer}) or an e-mail address, no target is offered and
20	 * the owner is left as plain text.
21	 *
22	 * <p>Registered as a global {@code gotoDeclarationHandler}; it self-filters by
23	 * matching only this language's owner token types, which are unique to
24	 * CODEOWNERS files, so it is inert in every other file.
25	 */
26	public final class CodeownersOwnerGotoDeclarationHandler implements GotoDeclarationHandler {
27	
28	  private static boolean isOwner(@Nullable IElementType type) {
29	    return type == CodeownersTokenTypes.USER_OWNER || type == CodeownersTokenTypes.TEAM_OWNER;
30	  }
31	
32	  @Override
33	  public PsiElement @Nullable [] getGotoDeclarationTargets(@Nullable PsiElement sourceElement,
34	                                                           int offset,
35	                                                           @Nullable Editor editor) {
36	    if (sourceElement == null) return null;
37	    ASTNode node = sourceElement.getNode();
38	    if (node == null || !isOwner(node.getElementType())) return null;
39	
40	    String owner = sourceElement.getText();
41	    if (owner == null || owner.isEmpty()) return null;
42	
43	    Project project = sourceElement.getProject();
44	    String url = CodeownersRemoteService.getInstance(project).ownerUrl(owner);
45	    if (url == null) return null;
46	
47	    return new PsiElement[]{new OpenUrlInBrowserElement(sourceElement, url)};
48	  }
49	}
