1	package net.wolfig.codeowls.explain;
2	
3	import com.intellij.openapi.actionSystem.ActionUpdateThread;
4	import com.intellij.openapi.actionSystem.AnActionEvent;
5	import com.intellij.openapi.actionSystem.CommonDataKeys;
6	import com.intellij.openapi.application.ModalityState;
7	import com.intellij.openapi.application.ReadAction;
8	import com.intellij.openapi.project.DumbAwareAction;
9	import com.intellij.openapi.project.Project;
10	import com.intellij.openapi.ui.popup.JBPopupFactory;
11	import com.intellij.openapi.vfs.VirtualFile;
12	import com.intellij.ui.awt.RelativePoint;
13	import com.intellij.util.concurrency.AppExecutorUtil;
14	import net.wolfig.codeowls.statusbar.CodeownersService;
15	import org.jetbrains.annotations.NotNull;
16	import org.jetbrains.annotations.Nullable;
17	
18	/**
19	 * Action that explains <em>why</em> the selected project file has its effective
20	 * CODEOWNERS owner(s): shows every matching rule in evaluation order, the
21	 * winning rule, section inheritance, and approval counts, with click-to-navigate
22	 * to each rule.
23	 *
24	 * <p>Registered on the Project View and Editor context menus (and reachable from
25	 * Find Action). Enabled only for a single real file — not a directory, and not a
26	 * CODEOWNERS file itself, since explaining a CODEOWNERS file's own ownership is
27	 * rarely what the user wants and the status-bar widget already covers the open
28	 * editor.
29	 *
30	 * <p>The ownership computation reuses {@link CodeownersService#explain} on a
31	 * non-blocking background read action — exactly as the status-bar widget does —
32	 * so the EDT never parses or matches. The popup is then shown on the EDT.
33	 */
34	public final class ExplainCodeownersOwnershipAction extends DumbAwareAction {
35	
36	  /**
37	   * The single file the action targets, or {@code null} when the selection is
38	   * not a single file (e.g. nothing selected, or a multi-selection).
39	   */
40	  private static @Nullable VirtualFile targetFile(@NotNull AnActionEvent e) {
41	    VirtualFile[] many = e.getData(CommonDataKeys.VIRTUAL_FILE_ARRAY);
42	    if (many != null && many.length > 1) return null;
43	    return e.getData(CommonDataKeys.VIRTUAL_FILE);
44	  }
45	
46	  private static boolean isExplainable(@Nullable VirtualFile file) {
47	    return file != null && file.isValid() && !file.isDirectory()
48	            && !"CODEOWNERS".equals(file.getName());
49	  }
50	
51	  @Override
52	  public void update(@NotNull AnActionEvent e) {
53	    e.getPresentation().setEnabledAndVisible(e.getProject() != null && isExplainable(targetFile(e)));
54	  }
55	
56	  @Override
57	  public @NotNull ActionUpdateThread getActionUpdateThread() {
58	    return ActionUpdateThread.BGT;
59	  }
60	
61	  @Override
62	  public void actionPerformed(@NotNull AnActionEvent e) {
63	    Project project = e.getProject();
64	    VirtualFile file = targetFile(e);
65	    if (project == null || !isExplainable(file)) return;
66	
67	    // Resolve the popup anchor now, on the EDT, rather than retaining the
68	    // DataContext across the background computation.
69	    RelativePoint where = JBPopupFactory.getInstance().guessBestPopupLocation(e.getDataContext());
70	
71	    ReadAction.nonBlocking(() -> CodeownersService.getInstance(project).explain(file))
72	            .expireWith(project)
73	            .finishOnUiThread(ModalityState.defaultModalityState(),
74	                    explanation -> OwnershipExplanationPopup.show(project, explanation, where))
75	            .submit(AppExecutorUtil.getAppExecutorService());
76	  }
77	}
