20	/**
21	 * Minimal parser definition for CODEOWNERS.
22	 *
23	 * <p>The parser does not build any meaningful AST structure — it wraps the
24	 * entire file content in a single root marker. This is sufficient to enable
25	 * the Language/PSI infrastructure (and therefore syntax highlighting) without
26	 * requiring a grammar file or generated parser.
27	 *
28	 * <p>A future annotator, inspection, or completion contributor can be added
29	 * without changing this definition by inspecting lexer tokens directly.
30	 */
31	public class CodeownersParserDefinition implements ParserDefinition {
32	
33	  public static final IFileElementType FILE =
34	          new IFileElementType(CodeownersLanguage.INSTANCE);
35	
36	  @Override
37	  public @NotNull Lexer createLexer(Project project) {
38	    return new CodeownersLexer();
39	  }
40	
41	  @Override
42	  public @NotNull PsiParser createParser(Project project) {
43	    return (root, builder) -> {
44	      PsiBuilder.Marker marker = builder.mark();
45	      while (!builder.eof()) {
46	        builder.advanceLexer();
47	      }
48	      marker.done(root);
49	      return builder.getTreeBuilt();
50	    };
51	  }
52	
53	  @Override
54	  public @NotNull IFileElementType getFileNodeType() {
55	    return FILE;
56	  }
57	
58	  @Override
59	  public @NotNull TokenSet getWhitespaceTokens() {
60	    return TokenSet.WHITE_SPACE;
61	  }
62	
63	  @Override
64	  public @NotNull TokenSet getCommentTokens() {
65	    return TokenSet.create(CodeownersTokenTypes.COMMENT);
66	  }
67	
68	  @Override
69	  public @NotNull TokenSet getStringLiteralElements() {
70	    return TokenSet.EMPTY;
71	  }
72	
73	  @Override
74	  public @NotNull PsiElement createElement(ASTNode node) {
75	    throw new AssertionError("No custom AST elements in CODEOWNERS: " + node.getElementType());
76	  }
77	
78	  @Override
79	  public @NotNull PsiFile createFile(@NotNull FileViewProvider viewProvider) {
80	    return new PsiFileBase(viewProvider, CodeownersLanguage.INSTANCE) {
81	      @Override
82	      public @NotNull FileType getFileType() {
83	        return CodeownersFileType.INSTANCE;
84	      }
85	    };
86	  }
87	}
