7	
8	import java.util.ArrayList;
9	import java.util.LinkedHashMap;
10	import java.util.List;
11	import java.util.Map;
12	
13	/**
14	 * Gathers owner suggestions from every source the plugin knows about and
15	 * de-duplicates them. The first source that mentions an owner wins, so
16	 * candidates are stable across invocations.
17	 *
18	 * <p>The structure makes it cheap to plug additional sources in later — a
19	 * Git-history walker, a plugin-settings-backed static list — without touching
20	 * the completion provider. v1 ships with the "current file" source only;
21	 * unavailable sources gracefully return no candidates.
22	 */
23	public final class CodeownersOwnerCollector {
24	
25	  public static final String SOURCE_CURRENT_FILE = "already used in CODEOWNERS";
26	  public static final String SOURCE_GIT_HISTORY = "from Git history";
27	  public static final String SOURCE_PLUGIN_SETTINGS = "from plugin settings";
28	  public static final String SOURCE_BUILTIN_ROLE = "GitLab role";
29	  private final List<Source> sources;
30	
31	  public CodeownersOwnerCollector() {
32	    this(List.of(new CurrentFileSource(), new CodeownersGitOwnerSource(), new BuiltinRoleSource()));
33	  }
34	
35	  /**
36	   * Test seam: supply a custom set of sources.
37	   */
38	  public CodeownersOwnerCollector(@NotNull List<Source> sources) {
39	    this.sources = List.copyOf(sources);
40	  }
41	
42	  public @NotNull List<OwnerCandidate> collect(@NotNull PsiFile codeownersFile) {
43	    Map<String, OwnerCandidate> byOwner = new LinkedHashMap<>();
44	    for (Source source : sources) {
45	      for (OwnerCandidate candidate : source.collect(codeownersFile)) {
46	        byOwner.putIfAbsent(candidate.owner(), candidate);
47	      }
48	    }
49	    return new ArrayList<>(byOwner.values());
50	  }
51	
52	  /**
53	   * Provides {@link OwnerCandidate}s. Implementations are expected to be
54	   * fast and side-effect-free; sources that require background work should
55	   * cache and return an empty list when results aren't ready yet.
56	   */
57	  public interface Source {
58	    @NotNull List<OwnerCandidate> collect(@NotNull PsiFile codeownersFile);
59	  }
60	
61	  /**
62	   * One owner string plus a short tail describing where it came from. The
63	   * source string is shown verbatim as the lookup element's type-text.
64	   */
65	  public record OwnerCandidate(@NotNull String owner, @NotNull String source) {
66	  }
67	
68	  /**
69	   * Collects every owner mentioned in the CODEOWNERS file being edited. This
70	   * is the highest-signal source — owners listed elsewhere in the same file
71	   * are almost always the right completion for a new rule.
72	   */
73	  public static final class CurrentFileSource implements Source {
74	    @Override
75	    public @NotNull List<OwnerCandidate> collect(@NotNull PsiFile codeownersFile) {
76	      CharSequence text = codeownersFile.getViewProvider().getContents();
77	      if (text.isEmpty()) return List.of();
78	      List<CodeownersRule> rules = CodeownersRuleParser.parse(text, codeownersFile.getVirtualFile());
79	      List<OwnerCandidate> out = new ArrayList<>();
80	      for (CodeownersRule rule : rules) {
81	        for (String owner : rule.owners()) {
82	          out.add(new OwnerCandidate(owner, SOURCE_CURRENT_FILE));
83	        }
84	      }
85	      return out;
86	    }
87	  }
88	
89	  /**
90	   * Surfaces the GitLab project roles ({@code @@developer}, {@code @@maintainer},
91	   * {@code @@owner}) as completion candidates. They're always available so
92	   * users don't need to remember the exact spelling or that two {@code @} signs
93	   * are required.
94	   */
95	  public static final class BuiltinRoleSource implements Source {
96	    private static final List<OwnerCandidate> ROLES = List.of(
97	            new OwnerCandidate("@@developer", SOURCE_BUILTIN_ROLE),
98	            new OwnerCandidate("@@maintainer", SOURCE_BUILTIN_ROLE),
99	            new OwnerCandidate("@@owner", SOURCE_BUILTIN_ROLE));
100	
101	    @Override
102	    public @NotNull List<OwnerCandidate> collect(@NotNull PsiFile codeownersFile) {
103	      return ROLES;
104	    }
105	  }
106	}
