28	/**
29	 * Marks CODEOWNERS rules that carry no weight: a pattern that matches no file
30	 * in the project (the path/glob does not exist), or a rule that is fully
31	 * shadowed by a later rule and therefore never decides ownership.
32	 *
33	 * <p>A pattern matching no file is reported as a warning (yellow underline) —
34	 * it is likely a mistake; a shadowed rule is dead code, so it gets the
35	 * greyed-out unused style. Both carry a quick fix that deletes the rule line.
36	 * The analysis ({@link CodeownersRedundancyAnalyzer}) walks the project tree,
37	 * so its result is cached on the CODEOWNERS {@link PsiFile} and recomputed only
38	 * when the PSI changes.
39	 */
40	public final class CodeownersUnnecessaryRuleInspection extends LocalInspectionTool {
41	
42	  /**
43	   * A non-existent path is a likely mistake worth a warning (yellow underline);
44	   * a shadowed rule is merely dead code, so it gets the greyed-out unused style.
45	   */
46	  private static @NotNull ProblemHighlightType highlightType(@NotNull CodeownersRedundancyAnalyzer.Kind kind) {
47	    return switch (kind) {
48	      case NO_FILES_MATCH -> ProblemHighlightType.WARNING;
49	      case SHADOWED -> ProblemHighlightType.LIKE_UNUSED_SYMBOL;
50	    };
51	  }
52	
53	  private static @NotNull String message(@NotNull Finding finding, @NotNull List<CodeownersRule> rules) {
54	    return switch (finding.kind()) {
55	      case NO_FILES_MATCH -> "Pattern matches no files in the project";
56	      case SHADOWED -> "Rule is shadowed by the rule on line "
57	              + (rules.get(finding.shadowingRuleIndex()).lineNumber() + 1)
58	              + " and never takes effect";
59	    };
60	  }
61	
62	  private static @NotNull Analysis analysisFor(@NotNull PsiFile file) {
63	    return CachedValuesManager.getCachedValue(file, () ->
64	            CachedValueProvider.Result.create(
65	                    compute(file), file, PsiModificationTracker.MODIFICATION_COUNT));
66	  }
67	
68	  private static @NotNull Analysis compute(@NotNull PsiFile file) {
69	    VirtualFile vf = file.getVirtualFile();
70	    VirtualFile root = CodeownersMatchCounter.projectRoot(vf);
71	    List<CodeownersRule> rules = CodeownersRuleParser.parse(file.getViewProvider().getContents(), vf);
72	    if (root == null || rules.isEmpty()) return new Analysis(rules, List.of());
73	    List<String> paths = CodeownersMatchCounter.collectProjectFilePaths(root);
74	    return new Analysis(rules, CodeownersRedundancyAnalyzer.analyze(rules, paths));
75	  }
76	
77	  private static @NotNull List<PsiElement> collectPatternTokens(@NotNull PsiFile file) {
78	    List<PsiElement> tokens = new ArrayList<>();
79	    PsiTreeUtil.processElements(file, (PsiElementProcessor<PsiElement>) element -> {
80	      ASTNode node = element.getNode();
81	      if (node != null && node.getElementType() == CodeownersTokenTypes.PATTERN) {
82	        tokens.add(element);
83	      }
84	      return true;
85	    });
86	    return tokens;
87	  }
88	
89	  @Override
90	  public ProblemDescriptor @Nullable [] checkFile(@NotNull PsiFile file,
91	                                                  @NotNull InspectionManager manager,
92	                                                  boolean isOnTheFly) {
93	    if (!file.getLanguage().is(CodeownersLanguage.INSTANCE)) return null;
94	
95	    Analysis analysis = analysisFor(file);
96	    if (analysis.findings().isEmpty()) return ProblemDescriptor.EMPTY_ARRAY;
97	
98	    List<PsiElement> patternTokens = collectPatternTokens(file);
99	    // Defensive: rules and PATTERN tokens are produced from the same content,
100	    // so they must align 1:1. If they somehow don't, skip rather than mis-mark.
101	    if (patternTokens.size() != analysis.rules().size()) return ProblemDescriptor.EMPTY_ARRAY;
102	
103	    List<ProblemDescriptor> problems = new ArrayList<>(analysis.findings().size());
104	    for (Finding finding : analysis.findings()) {
105	      PsiElement token = patternTokens.get(finding.ruleIndex());
106	      problems.add(manager.createProblemDescriptor(
107	              token,
108	              message(finding, analysis.rules()),
109	              new RemoveRuleQuickFix(),
110	              highlightType(finding.kind()),
111	              isOnTheFly));
112	    }
113	    return problems.toArray(ProblemDescriptor.EMPTY_ARRAY);
114	  }
115	
116	  private record Analysis(@NotNull List<CodeownersRule> rules, @NotNull List<Finding> findings) {
117	  }
118	
119	  /**
120	   * Deletes the whole line of the flagged rule. Runs in the platform-provided
121	   * write action, so it edits the document directly.
122	   */
123	  private static final class RemoveRuleQuickFix implements LocalQuickFix {
124	
125	    @Override
126	    public @NotNull String getFamilyName() {
127	      return "Remove CODEOWNERS rule";
128	    }
129	
130	    @Override
131	    public void applyFix(@NotNull Project project, @NotNull ProblemDescriptor descriptor) {
132	      PsiElement element = descriptor.getPsiElement();
133	      if (element == null || !element.isValid()) return;
134	      PsiFile file = element.getContainingFile();
135	      if (file == null) return;
136	      Document document = file.getViewProvider().getDocument();
137	      if (document == null) return;
138	
139	      int line = document.getLineNumber(element.getTextRange().getStartOffset());
140	      int start = document.getLineStartOffset(line);
141	      int end = line + 1 < document.getLineCount()
142	              ? document.getLineStartOffset(line + 1)
143	              : document.getTextLength();
144	      document.deleteString(start, end);
145	      PsiDocumentManager.getInstance(project).commitDocument(document);
146	    }
147	  }
148	}
