27	/**
28	 * Computes and shows owner suggestions for a file that has no CODEOWNERS owner.
29	 *
30	 * <p>Triggered by clicking the status-bar widget. Resolving the CODEOWNERS
31	 * context, gathering completion candidates, and especially the per-file
32	 * {@code git log} all happen on a background task; the chooser popup is then
33	 * shown on the EDT. Picking a suggestion appends a rule
34	 * ({@code /relative/path @owner}) to the CODEOWNERS file and opens it there.
35	 *
36	 * <p>If no CODEOWNERS file governs the target, nothing is shown — there would be
37	 * nowhere to add the rule.
38	 */
39	public final class CodeownersSuggestionPopup {
40	
41	  private CodeownersSuggestionPopup() {
42	  }
43	
44	  public static void show(@NotNull Project project, @NotNull VirtualFile target, @NotNull RelativePoint where) {
45	    new Task.Backgroundable(project, "Computing CODEOWNERS Suggestions", true) {
46	      private List<OwnerSuggestion> suggestions = List.of();
47	      private CodeownersService.FileContext context;
48	
49	      @Override
50	      public void run(@NotNull ProgressIndicator indicator) {
51	        CodeownersService.FileContext ctx =
52	                ReadAction.compute(() -> CodeownersService.getInstance(project).fileContext(target));
53	        if (ctx == null) return;
54	        context = ctx;
55	
56	        List<OwnerCandidate> candidates = ReadAction.compute(() -> {
57	          PsiFile psi = PsiManager.getInstance(project).findFile(ctx.codeownersFile());
58	          return psi == null ? List.<OwnerCandidate>of() : new CodeownersOwnerCollector().collect(psi);
59	        });
60	
61	        Map<String, Integer> authors =
62	                CodeownersGitContributorService.getInstance(project).getFileAuthorCommits(target);
63	
64	        suggestions = CodeownersOwnerSuggester.suggest(
65	                ctx.relativePath(), ctx.rules(), candidates, authors);
66	      }
67	
68	      @Override
69	      public void onSuccess() {
70	        if (project.isDisposed() || context == null || suggestions.isEmpty()) return;
71	        showChooser(project, context, suggestions, where);
72	      }
73	    }.queue();
74	  }
75	
76	  private static void showChooser(@NotNull Project project,
77	                                  @NotNull CodeownersService.FileContext context,
78	                                  @NotNull List<OwnerSuggestion> suggestions,
79	                                  @NotNull RelativePoint where) {
80	    JBPopupFactory.getInstance()
81	            .createPopupChooserBuilder(suggestions)
82	            .setTitle("Suggested Owners for " + context.relativePath())
83	            .setRenderer(new ColoredListCellRenderer<OwnerSuggestion>() {
84	              @Override
85	              protected void customizeCellRenderer(@NotNull JList<? extends OwnerSuggestion> list,
86	                                                   OwnerSuggestion value, int index,
87	                                                   boolean selected, boolean hasFocus) {
88	                if (value != null) append(format(value));
89	              }
90	            })
91	            .setItemChosenCallback(suggestion ->
92	                    insertRule(project, context.codeownersFile(), context.relativePath(), suggestion.owner()))
93	            .createPopup()
94	            .show(where);
95	  }
96	
97	  /**
98	   * e.g. {@code "@api-team — 78%  ·  already used in CODEOWNERS"}
99	   */
100	  static @NotNull String format(@NotNull OwnerSuggestion s) {
101	    return s.owner() + "  —  " + s.confidencePercent() + "%  ·  " + s.source();
102	  }
103	
104	  private static void insertRule(@NotNull Project project, @NotNull VirtualFile codeownersFile,
105	                                 @NotNull String relativePath, @NotNull String owner) {
106	    if (!codeownersFile.isValid()) return;
107	    int[] ruleLine = {-1};
108	    WriteCommandAction.runWriteCommandAction(project, "Add CODEOWNERS Rule", null, () -> {
109	      Document document = FileDocumentManager.getInstance().getDocument(codeownersFile);
110	      if (document == null) return;
111	      CharSequence text = document.getCharsSequence();
112	      String separator = text.isEmpty() || text.charAt(text.length() - 1) == '\n' ? "" : "\n";
113	      int ruleOffset = document.getTextLength() + separator.length();
114	      document.insertString(document.getTextLength(), separator + "/" + relativePath + " " + owner + "\n");
115	      FileDocumentManager.getInstance().saveDocument(document);
116	      ruleLine[0] = document.getLineNumber(Math.min(ruleOffset, Math.max(document.getTextLength() - 1, 0)));
117	    });
118	    // Navigate after the write completes, not from inside the write action.
119	    if (ruleLine[0] >= 0) {
120	      new OpenFileDescriptor(project, codeownersFile, ruleLine[0], 0).navigate(true);
121	    }
122	  }
123	}
