3	import org.jetbrains.annotations.NotNull;
4	import org.jetbrains.annotations.Nullable;
5	
6	import java.util.List;
7	
8	/**
9	 * A parsed GitLab section header, e.g. {@code [Backend][2] @org/backend @alice}
10	 * or {@code ^[Optional]}.
11	 *
12	 * <p>Attached to every {@link CodeownersRule} that falls under the section so
13	 * that an ownership explanation can show <em>why</em> a rule has the owners and
14	 * approval count it does — the inheritance that {@link CodeownersRuleParser}
15	 * otherwise bakes irreversibly into {@link CodeownersRule#owners()}.
16	 *
17	 * @param name          the section name between the brackets (e.g. {@code Backend})
18	 * @param optional      {@code true} for a {@code ^[Section]} optional section
19	 * @param defaultOwners owners declared on the header line, inherited by rules
20	 *                      in the section that name none of their own
21	 * @param approvalCount the section's required approval count ({@code [Backend][2]}),
22	 *                      or {@code null} when the header declares none
23	 */
24	public record CodeownersSection(
25	        @NotNull String name,
26	        boolean optional,
27	        @NotNull List<String> defaultOwners,
28	        @Nullable Integer approvalCount) {
29	
30	  /**
31	   * Renders the header roughly as it appears in the file, e.g.
32	   * {@code ^[Backend][2] @org/backend}. Used for display in the ownership
33	   * explanation.
34	   */
35	  public @NotNull String displayHeader() {
36	    StringBuilder sb = new StringBuilder();
37	    if (optional) sb.append('^');
38	    sb.append('[').append(name).append(']');
39	    if (approvalCount != null) sb.append('[').append(approvalCount).append(']');
40	    for (String owner : defaultOwners) sb.append(' ').append(owner);
41	    return sb.toString();
42	  }
43	}
