2	
3	import org.jetbrains.annotations.NotNull;
4	
5	/**
6	 * Decides whether the caret in a CODEOWNERS file is currently in a pattern
7	 * segment, an owner segment, the name of a section header, a comment, or
8	 * somewhere completion shouldn't fire at all.
9	 *
10	 * <p>The decision is purely line-text-based — we scan the characters from the
11	 * start of the current line up to the caret. That's enough to be correct
12	 * (CODEOWNERS rules don't span multiple lines) and avoids depending on the
13	 * intermediate "dummy identifier" PSI state that completion otherwise inserts.
14	 *
15	 * <p>Section header lines have two completion-relevant positions: inside the
16	 * primary {@code [Name]} brackets (where we want to suggest section names) and
17	 * after the closing bracket(s) (where GitLab allows default owners — handled
18	 * by the regular owner provider, so we report {@link Segment#OWNER} there).
19	 */
20	public final class CodeownersCompletionContext {
21	
22	  private final Segment segment;
23	  private final String typedSegmentText;
24	
25	  private CodeownersCompletionContext(@NotNull Segment segment, @NotNull String typedSegmentText) {
26	    this.segment = segment;
27	    this.typedSegmentText = typedSegmentText;
28	  }
29	
30	  /**
31	   * Analyse the prefix of the current line ending at the caret offset.
32	   *
33	   * @param lineBeforeCaret characters from the start of the line up to (but
34	   *                        not including) the caret offset
35	   */
36	  public static @NotNull CodeownersCompletionContext fromLinePrefix(@NotNull CharSequence lineBeforeCaret) {
37	    int n = lineBeforeCaret.length();
38	    int i = skipHSpace(lineBeforeCaret, 0, n);
39	
40	    if (i == n) {
41	      // Empty or whitespace-only line — caret position is where a new pattern starts.
42	      return new CodeownersCompletionContext(Segment.PATTERN, "");
43	    }
44	
45	    char first = lineBeforeCaret.charAt(i);
46	    if (first == '#') {
47	      return new CodeownersCompletionContext(Segment.COMMENT, "");
48	    }
49	
50	    int sectionBracketOpen = sectionBracketOpenAt(lineBeforeCaret, i, n);
51	    if (sectionBracketOpen >= 0) {
52	      return analyzeSectionHeader(lineBeforeCaret, sectionBracketOpen, n);
53	    }
54	
55	    return analyzeRuleLine(lineBeforeCaret, i, n);
56	  }
57	
58	  /**
59	   * @return the offset of the first {@code [} of a section header (handling
60	   * the optional {@code ^} GitLab prefix), or -1 if the line doesn't start one.
61	   */
62	  private static int sectionBracketOpenAt(@NotNull CharSequence text, int i, int n) {
63	    if (text.charAt(i) == '[') return i;
64	    if (text.charAt(i) == '^' && i + 1 < n && text.charAt(i + 1) == '[') return i + 1;
65	    return -1;
66	  }
67	
68	  /**
69	   * Caret is on a section header line; figure out where exactly.
70	   * <ul>
71	   *   <li>Inside the first {@code [...]} → section name completion.</li>
72	   *   <li>Inside a following approval-count {@code [N]} → neutral.</li>
73	   *   <li>After all brackets with whitespace before the caret → owner completion.</li>
74	   *   <li>Right after {@code ]} with no whitespace yet → neutral.</li>
75	   * </ul>
76	   */
77	  private static @NotNull CodeownersCompletionContext analyzeSectionHeader(
78	          @NotNull CharSequence text, int firstBracketOpen, int n) {
79	    int firstClose = indexOfChar(text, firstBracketOpen + 1, n, ']');
80	    if (firstClose < 0) {
81	      String typed = text.subSequence(firstBracketOpen + 1, n).toString();
82	      return new CodeownersCompletionContext(Segment.SECTION_HEADER_NAME, typed);
83	    }
84	    int after = firstClose + 1;
85	    if (after < n && text.charAt(after) == '[') {
86	      int approvalClose = indexOfChar(text, after + 1, n, ']');
87	      if (approvalClose < 0) {
88	        // Caret sits inside the approval-count brackets — nothing useful to offer.
89	        return new CodeownersCompletionContext(Segment.NONE, "");
90	      }
91	      after = approvalClose + 1;
92	    }
93	    return analyzeOwnerArea(text, after, n);
94	  }
95	
96	  /**
97	   * Regular rule line — first whitespace separates pattern from owner segment.
98	   */
99	  private static @NotNull CodeownersCompletionContext analyzeRuleLine(
100	          @NotNull CharSequence text, int start, int n) {
101	    int patternEnd = start;
102	    while (patternEnd < n && !isHSpace(text.charAt(patternEnd))) patternEnd++;
103	    if (patternEnd >= n) {
104	      String typed = text.subSequence(start, n).toString();
105	      return new CodeownersCompletionContext(Segment.PATTERN, typed);
106	    }
107	    return analyzeOwnerArea(text, patternEnd, n);
108	  }
109	
110	  /**
111	   * Common owner-segment analysis. Requires at least one whitespace between
112	   * {@code afterEnd} and the caret — otherwise the caret is wedged against
113	   * the previous token and offering owner suggestions there would emit
114	   * invalid syntax (e.g. {@code [Backend]@owner}).
115	   */
116	  private static @NotNull CodeownersCompletionContext analyzeOwnerArea(
117	          @NotNull CharSequence text, int afterEnd, int n) {
118	    int j = afterEnd;
119	    int whitespaceConsumed = 0;
120	    while (j < n && isHSpace(text.charAt(j))) {
121	      j++;
122	      whitespaceConsumed++;
123	    }
124	    if (whitespaceConsumed == 0) {
125	      // No whitespace gap before the caret — not yet in the owner segment.
126	      return new CodeownersCompletionContext(Segment.NONE, "");
127	    }
128	    int ownerStart = j;
129	    for (int k = j; k < n; k++) {
130	      if (isHSpace(text.charAt(k))) ownerStart = k + 1;
131	    }
132	    String typedOwner = ownerStart >= n ? "" : text.subSequence(ownerStart, n).toString();
133	    return new CodeownersCompletionContext(Segment.OWNER, typedOwner);
134	  }
135	
136	  private static int skipHSpace(@NotNull CharSequence text, int from, int to) {
137	    int i = from;
138	    while (i < to && isHSpace(text.charAt(i))) i++;
139	    return i;
140	  }
141	
142	  private static int indexOfChar(@NotNull CharSequence text, int from, int to, char target) {
143	    for (int i = from; i < to; i++) {
144	      if (text.charAt(i) == target) return i;
145	    }
146	    return -1;
147	  }
148	
149	  private static boolean isHSpace(char c) {
150	    return c == ' ' || c == '\t';
151	  }
152	
153	  /**
154	   * @return the segment the caret is in.
155	   */
156	  public @NotNull Segment segment() {
157	    return segment;
158	  }
159	
160	  /**
161	   * @return the text typed so far within the current segment (the partial
162	   * pattern, the partial owner token, or the partial section name). Empty for
163	   * comments, neutral positions, or when the caret sits at the start of an
164	   * otherwise empty position.
165	   */
166	  public @NotNull String typedSegmentText() {
167	    return typedSegmentText;
168	  }
169	
170	  public enum Segment {
171	    /**
172	     * Caret is in the pattern part — first whitespace-delimited token on the line.
173	     */
174	    PATTERN,
175	    /**
176	     * Caret is in an owner position: after a rule pattern OR after a section header's bracket(s).
177	     */
178	    OWNER,
179	    /**
180	     * Caret is inside a {@code #} comment; no completion.
181	     */
182	    COMMENT,
183	    /**
184	     * Caret is inside the name brackets of a section header ({@code [Backend]}).
185	     */
186	    SECTION_HEADER_NAME,
187	    /**
188	     * Caret is somewhere completion shouldn't fire (e.g. inside an approval count or a stray bracket).
189	     */
190	    NONE,
191	  }
192	}
