1	package net.wolfig.codeowls.refactoring;
2	
3	import org.jetbrains.annotations.NotNull;
4	import org.jetbrains.annotations.Nullable;
5	
6	/**
7	 * Rewrites a single CODEOWNERS pattern when the path it targets is moved or
8	 * renamed. Pure string logic with no IntelliJ dependencies, so it is unit-tested
9	 * directly.
10	 *
11	 * <p>Only patterns that <em>literally reference</em> the moved path are rewritten:
12	 * the exact path, the directory forms ({@code path/}, {@code path/**}), and
13	 * anything nested under a moved directory ({@code path/sub/…}, {@code path/*.ext}).
14	 * A leading {@code !} (negation) and {@code /} (anchor) are preserved. Basename
15	 * rules and unrelated globs (e.g. {@code *.java}) are left untouched — moving a
16	 * file does not change which basenames a glob would match.
17	 *
18	 * <p>Paths are repo-relative, forward-slash, with no leading or trailing slash.
19	 */
20	public final class CodeownersPathRewriter {
21	
22	  private CodeownersPathRewriter() {
23	  }
24	
25	  /**
26	   * @return the rewritten pattern, or {@code null} if {@code pattern} does not
27	   * reference {@code oldPath} and so should be left unchanged.
28	   */
29	  public static @Nullable String rewritePattern(@NotNull String pattern,
30	                                                @NotNull String oldPath,
31	                                                @NotNull String newPath) {
32	    String core = pattern;
33	    String prefix = "";
34	    if (core.startsWith("!")) {
35	      prefix = "!";
36	      core = core.substring(1);
37	    }
38	    if (core.startsWith("/")) {
39	      prefix += "/";
40	      core = core.substring(1);
41	    }
42	
43	    String rewritten;
44	    if (core.equals(oldPath)) {
45	      rewritten = newPath;
46	    } else if (core.startsWith(oldPath + "/")) {
47	      // Nested under a moved directory: keep the suffix, swap the prefix.
48	      rewritten = newPath + core.substring(oldPath.length());
49	    } else {
50	      return null;
51	    }
52	    return prefix + rewritten;
53	  }
54	}
