@Test
public void ownerAfterAnInlineHash_followsTheLexer() {
  // Arrange — the CODEOWNERS lexer only knows whole-line comments: after a
  // rule's pattern, "#" is a bad character and a following "@name" is still
  // lexed (and highlighted) as an owner. The refactoring deliberately agrees
  // with the parser rather than inventing an inline-comment rule of its own.
  String content = "/api/** @alice # @alice reviews\n";

  // Act
  String result = refactor(content, offsetOf(content, "@alice", 0), "@bob", OwnerRefactoringScope.FILE);

  // Assert
  assertEquals("/api/** @bob # @bob reviews\n", result);
}

